def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def solve_problem():
    solutions = []

    # Step 1: Iterate over n in [151, 199] such that gcd(n, 6) = 1
    for n in range(151, 200):
        if math.gcd(n, 6) != 1:
            continue

        # Step 2: Determine the range for a: floor(n/a) = 2
        # This means 2 <= n/a < 3, or n/3 < a <= n/2.
        a_min = math.floor(n / 3) + 1
        a_max = math.floor(n / 2)

        if a_min > a_max:
            # This should theoretically not happen for n >= 2, but safe check.
            continue

        # Step 3 & 4: Iterate over a, calculate D=k, and check divisibility
        for a in range(a_min, a_max + 1):
            D = n - 2 * a  # D = k = n - 2a

            # Check prerequisites for binomial coefficient:
            # We need a-1 >= D-1 >= 0.
            # Since a_min > n/3, 3a > n, so a > n-2a = D. Thus a-1 >= D.
            # Since a_max <= n/2, 2a <= n, so D >= 0.
            # Since n is odd (gcd(n, 2)=1), D = n-2a must be odd, so D >= 1.

            if D < 1:
                # Should not happen based on initial range setup, but defensively skip.
                continue

            # We check if D divides C(a-1, D-1)

            # Parameters for the binomial coefficient: N = a-1, K = D-1
            N = a - 1
            K = D - 1

            try:
                B = combinations(N, K)
            except ValueError:
                 # Should not happen given the derived constraints
                B = -1 

            if B == -1:
                continue

            # Step 5: Check divisibility
            if B % D == 0:
                solutions.append({
                    'n': n, 
                    'a': a, 
                    'D': D, 
                    'B': B, 
                    'is_solution': True
                })
            else:
                # Optional: record non-solutions for completeness if needed, 
                # but the task only asks to record solutions found.
                pass

    # Formatting output for notes.md
    output = []
    for sol in solutions:
        output.append(f"N={sol['n']}, A={sol['a']}, D={sol['D']}: {sol['B']} is divisible by {sol['D']}.")

    return "\n".join(output)

